// This is just a test, and I haven't been working with GLSL (OpenGL Shading Language) for long.
// Flying through starry sky shader by melcom (www.melcom-music.de)

// Funktion zur Erzeugung von Rauschen / Function to create noise
float random(vec2 st) {
    return fract(sin(dot(st.xy, vec2(12.9898, 78.233))) * 43758.5453123);
}

// Funktion zur Erzeugung eines Rausch-Effekts / Function to create a noisy effect
float noise(vec2 st) {
    vec2 i = floor(st);
    vec2 f = fract(st);

    float a = random(i);
    float b = random(i + vec2(1.0, 0.0));
    float c = random(i + vec2(0.0, 1.0));
    float d = random(i + vec2(1.0, 1.0));

    vec2 u = f * f * (3.0 - 2.0 * f);

    return mix(a, b, u.x) + (c - a) * u.y * (1.0 - u.x) + (d - b) * u.x * u.y;
}

// Funktion zur Erzeugung eines funkelnden Sterns / Function to create a twinkling star
float star(vec2 uv, vec3 pos, float size, float brightness) {
    vec2 position = pos.xy / pos.z;
    float d = distance(uv, position);
    return brightness * smoothstep(size, size * 0.5, d);
}

// Hauptfunktion für das Bild / Main image function
void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = fragCoord.xy / iResolution.xy * 2.0 - 1.0; // Normierung der UV-Koordinaten für den gesamten Bildschirm / Normalize UV coordinates to cover the entire screen
    uv.x *= iResolution.x / iResolution.y; // Skalierung basierend auf dem Seitenverhältnis / Scale based on aspect ratio

    // Hintergrundfarbe / Background color
    vec3 color = vec3(0.0, 0.0, 0.1); // Dunkelblau / Dark blue

    // Hinzufügen von Sternen / Adding stars
    for (int i = 0; i < 100; i++) {
        float depth = fract(float(i) * 0.1 - iTime * 0.1); // Vorwärtsbewegung / Forward movement
        vec3 starPos = vec3(random(vec2(float(i), float(i) + 1.0)) * 2.0 - 1.0, random(vec2(float(i) + 2.0, float(i) + 3.0)) * 2.0 - 1.0, depth); // Position anpassen / Adjust position
        float starSize = random(vec2(float(i) + 4.0, float(i) + 5.0)) * 0.005 / depth;
        float starBrightness = random(vec2(float(i) + 6.0, float(i) + 7.0)) * 0.8 + 0.2;
        color += star(uv, starPos, starSize, starBrightness);
    }

    fragColor = vec4(color, 1.0); // Setzen der finalen Fragmentfarbe / Setting the final fragment color
}
